PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS schema_migrations (version INTEGER PRIMARY KEY, checksum TEXT NOT NULL, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS workspaces (id TEXT PRIMARY KEY, name TEXT NOT NULL, root_handle TEXT NOT NULL UNIQUE, status TEXT NOT NULL CHECK (status IN ('ACTIVE','READ_ONLY')), version INTEGER NOT NULL CHECK (version >= 1), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS tasks (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE RESTRICT, owner_kind TEXT NOT NULL CHECK (owner_kind = 'workspace'), owner_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE RESTRICT, title TEXT NOT NULL, status TEXT NOT NULL CHECK (status IN ('CREATED','RUNNING','COMPLETED','CANCELLED')), version INTEGER NOT NULL CHECK (version >= 1), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS domain_events (seq INTEGER PRIMARY KEY AUTOINCREMENT, event_id TEXT NOT NULL UNIQUE, workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE RESTRICT, aggregate_type TEXT NOT NULL, aggregate_id TEXT NOT NULL, aggregate_version INTEGER NOT NULL CHECK (aggregate_version >= 1), event_type TEXT NOT NULL, occurred_at TEXT NOT NULL, actor_id TEXT NOT NULL, correlation_id TEXT NOT NULL, causation_id TEXT, schema_version INTEGER NOT NULL CHECK (schema_version >= 1), payload TEXT NOT NULL CHECK (json_valid(payload)), UNIQUE (aggregate_type, aggregate_id, aggregate_version));
CREATE TABLE IF NOT EXISTS agent_runs (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE RESTRICT, task_id TEXT NOT NULL REFERENCES tasks(id) ON DELETE RESTRICT, definition_id TEXT NOT NULL, definition_version INTEGER NOT NULL, runtime TEXT NOT NULL CHECK (runtime IN ('native','langgraph')), status TEXT NOT NULL CHECK (status IN ('CREATED','RUNNING','WAITING_APPROVAL','PAUSED','COMPLETED','FAILED','CANCELLED')), version INTEGER NOT NULL CHECK (version >= 1), last_seq INTEGER NOT NULL DEFAULT 0 CHECK (last_seq >= 0), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS agent_events (global_seq INTEGER PRIMARY KEY AUTOINCREMENT, event_id TEXT NOT NULL UNIQUE, run_id TEXT NOT NULL REFERENCES agent_runs(id) ON DELETE RESTRICT, run_seq INTEGER NOT NULL CHECK (run_seq >= 1), workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE RESTRICT, type TEXT NOT NULL, occurred_at TEXT NOT NULL, correlation_id TEXT NOT NULL, payload TEXT NOT NULL CHECK (json_valid(payload)), UNIQUE (run_id, run_seq));
CREATE TABLE IF NOT EXISTS approvals (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE RESTRICT, run_id TEXT REFERENCES agent_runs(id) ON DELETE RESTRICT, capability TEXT NOT NULL, scope TEXT NOT NULL CHECK (json_valid(scope)), reason TEXT NOT NULL, risk_level TEXT NOT NULL CHECK (risk_level IN ('LOW','MEDIUM','HIGH','PROTECTED')), payload_hash TEXT NOT NULL, tool_version TEXT NOT NULL, policy_version TEXT NOT NULL, requested_at TEXT NOT NULL, expires_at TEXT NOT NULL, resolved_at TEXT, decision TEXT NOT NULL CHECK (decision IN ('PENDING','APPROVED','DENIED','EXPIRED')), consumed_at TEXT);
CREATE TABLE IF NOT EXISTS permissions (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE RESTRICT, actor_id TEXT NOT NULL, run_id TEXT REFERENCES agent_runs(id) ON DELETE RESTRICT, task_id TEXT REFERENCES tasks(id) ON DELETE RESTRICT, capability TEXT NOT NULL, scope TEXT NOT NULL CHECK (json_valid(scope)), granted_at TEXT NOT NULL, expires_at TEXT NOT NULL, revoked_at TEXT, policy_version TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS managed_files (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE RESTRICT, relative_path TEXT NOT NULL, sha256 TEXT NOT NULL, size_bytes INTEGER NOT NULL CHECK (size_bytes >= 0), state TEXT NOT NULL CHECK (state IN ('STAGED','ACTIVE','TRASH','MISSING')), original_ref TEXT, created_at TEXT NOT NULL, UNIQUE (workspace_id, relative_path));
CREATE TABLE IF NOT EXISTS artifacts (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE RESTRICT, run_id TEXT REFERENCES agent_runs(id) ON DELETE RESTRICT, managed_file_id TEXT NOT NULL REFERENCES managed_files(id) ON DELETE RESTRICT, kind TEXT NOT NULL, sha256 TEXT NOT NULL, created_at TEXT NOT NULL, version INTEGER NOT NULL CHECK (version >= 1));
CREATE TABLE IF NOT EXISTS settings_refs (workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE RESTRICT, key TEXT NOT NULL, value TEXT NOT NULL CHECK (json_valid(value)), credential_ref TEXT, PRIMARY KEY (workspace_id, key));
CREATE TABLE IF NOT EXISTS recycle_bin (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE RESTRICT, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, deleted_at TEXT NOT NULL, purge_after TEXT NOT NULL, restore_metadata TEXT NOT NULL CHECK (json_valid(restore_metadata)), version INTEGER NOT NULL, UNIQUE (entity_type, entity_id));
CREATE TABLE IF NOT EXISTS command_receipts (command_id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE RESTRICT, payload_hash TEXT NOT NULL, entity_id TEXT NOT NULL, entity_version INTEGER NOT NULL, event_ids TEXT NOT NULL CHECK (json_valid(event_ids)), completed_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS projection_offsets (workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE RESTRICT, projection_name TEXT NOT NULL, last_seq INTEGER NOT NULL CHECK (last_seq >= 0), PRIMARY KEY (workspace_id, projection_name));
CREATE TABLE IF NOT EXISTS tool_invocations (invocation_id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES agent_runs(id) ON DELETE RESTRICT, tool_id TEXT NOT NULL, tool_version TEXT NOT NULL, payload_hash TEXT NOT NULL, status TEXT NOT NULL CHECK (status IN ('STARTED','SUCCEEDED','FAILED','UNKNOWN')), effect_receipt TEXT CHECK (effect_receipt IS NULL OR json_valid(effect_receipt)));
CREATE INDEX IF NOT EXISTS tasks_workspace_status ON tasks(workspace_id, status);
CREATE INDEX IF NOT EXISTS approvals_pending ON approvals(workspace_id, decision, expires_at);
CREATE INDEX IF NOT EXISTS domain_events_workspace_order ON domain_events(workspace_id, seq);
CREATE INDEX IF NOT EXISTS agent_events_run_order ON agent_events(run_id, run_seq);
